INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(47929865, 'Magidog', '魔法犬', 'マジドッグ', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1700, 1000, '这张卡被魔法师族怪兽的同调召唤使用送去墓地的场合，可以选择自己墓地存在的1张场地魔法卡加入手卡。'),
(54408264, 'Magikey Battle', '魔键斗争', '魔鍵闘争', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以自己墓地的通常怪兽、「魔键」怪兽、「魔键-马夫提亚」之内1张为对象才能发动。那张卡回到卡组。连锁对方的魔法·陷阱·怪兽的效果的发动把这张卡发动的场合，再让衍生物以外的自己场上的通常怪兽以及「魔键」怪兽不受那个对方的效果影响。'),
(45655875, 'Magikey Beast - Ansyalabolas', '魔键召兽-安希亚拉波斯', '魔鍵召獣－アンシャラボラス', 'Fusion Monster', 'Beast', 'DARK', 4, 2200, 2000, '「魔键」怪兽＋衍生物以外的通常怪兽 这个卡名的①的效果1回合只能使用1次。 ①：这张卡融合召唤成功的场合才能发动。从自己墓地选1张「魔键-马夫提亚」加入手卡。 ②：1回合1次，以持有和自己墓地的通常怪兽或者「魔键」怪兽的其中任意种相同属性的1只对方的攻击表示怪兽为对象才能发动。那只怪兽变成守备表示，那个守备力下降1000。 ③：这张卡战斗破坏的怪兽不去墓地而除外。'),
(26988374, 'Magikey Deity - Ashtartu', '魔键凭神-阿斯塔尔图', '魔鍵憑神－アシュタルトゥ', 'XYZ Monster', 'Fairy', 'LIGHT', 8, 3000, 3000, '8星怪兽×2 ①：1回合1次，自己的通常怪兽或者「魔键」怪兽战斗破坏对方怪兽时，把这张卡1个超量素材取除才能发动。给与对方那只破坏的怪兽的原本攻击力数值的伤害。 ②：对方主要阶段1次，以持有和自己的场上·墓地的通常怪兽或者「魔键」怪兽的其中任意种相同属性的对方场上1只怪兽为对象才能发动。这张卡1个超量素材取除，作为对象的怪兽除外。'),
(71159974, 'Magikey Dragon - Andrabime', '魔键召龙-安托比姆斯', '魔鍵召竜－アンドラビムス', 'Fusion Monster', 'Dragon', 'WIND', 8, 2800, 2000, '「魔键」效果怪兽＋衍生物以外的通常怪兽 ①：在这张卡的融合召唤成功时对方不能把效果发动。 ②：1回合1次，以自己墓地1只通常怪兽或者「魔键」怪兽为对象才能发动。持有和那只怪兽相同属性的对方场上的怪兽全部破坏。 ③：作为这张卡的融合素材的怪兽的属性是2种类的场合，1回合1次，持有和自己墓地的其中任意种的怪兽相同属性的对方怪兽被战斗·效果破坏的场合才能发动。自己从卡组抽1张。'),
(51510279, 'Magikey Duo', '联结之魔键', '繋がれし魔鍵', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只通常怪兽或者「魔键」怪兽为对象才能发动。那只怪兽加入手卡。那之后，可以从以下效果选1个适用。 ●从自己的手卡·场上把「魔键」融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组守备表示融合召唤。 ●等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，从手卡把1只「魔键」仪式怪兽守备表示仪式召唤。'),
(69522668, 'Magikey Fiend - Transfurlmine', '魔键变鬼-特兰斯佛尔米雷', '魔鍵変鬼－トランスフルミネ', 'Synchro Monster', 'Thunder', 'FIRE', 8, 2800, 2800, '「魔键」调整＋调整以外的通常怪兽1只以上 这个卡名的②③的效果1回合各能使用1次。 ①：这张卡在同1次的战斗阶段中最多2次可以向怪兽攻击。 ②：作为这张卡的同调素材的怪兽的属性是2种类以上的场合才能发动。从卡组选1张「魔键」魔法·陷阱卡在自己的魔法与陷阱区域盖放。 ③：持有和自己墓地的其中任意种的怪兽相同属性的怪兽由对方召唤·特殊召唤的场合才能发动。那些怪兽破坏。'),
(40493210, 'Magikey Locking', '魔键锭-施-', '魔鍵錠－施－', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把衍生物以外的自己场上1只通常怪兽或者「魔键」怪兽解放，等级合计最多到8星以下为止以自己墓地最多2只通常怪兽或者「魔键」怪兽为对象才能发动。那些怪兽守备表示特殊召唤。那之后，可以从以下效果选1个适用。 ●用自己场上的怪兽为同调素材把1只「魔键」同调怪兽同调召唤。 ●用自己场上的怪兽为超量素材把1只「魔键」超量怪兽超量召唤。'),
(99426088, 'Magikey Maftea', '魔键-马夫提亚', '魔鍵－マフテア', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：「魔键」融合怪兽卡决定的融合素材怪兽从自己的手卡·场上送去墓地，把那1只融合怪兽从额外卡组融合召唤。或者，等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，从手卡把1只「魔键」仪式怪兽仪式召唤。自己场上有通常怪兽存在的场合，也能作为融合素材怪兽或者要为仪式召唤而解放的怪兽来把卡组1只通常怪兽送去墓地。'),
(45877457, 'Magikey Mechmortar - Garesglasser', '魔键炮-加雷斯维特', '魔鍵砲－ガレスヴェート', 'Ritual Effect Monster', 'Machine', 'EARTH', 8, 2000, 2800, '「魔键-马夫提亚」降临。这个卡名的②③的效果1回合各能使用1次。 ①：这张卡的攻击力上升自己墓地的怪兽的属性种类×300。 ②：这张卡的仪式召唤使用的怪兽的属性是2种类以上的场合，持有和自己墓地的其中任意种的怪兽相同属性的怪兽的效果由对方发动时才能发动。那个发动无效并破坏。 ③：仪式召唤的这张卡被送去墓地的场合才能发动。从卡组把1只「魔键」怪兽加入手卡。'),
(19489718, 'Magikey Mechmusket - Batosbuster', '魔键铳-巴托斯巴斯特', '魔鍵銃－バトスバスター', 'Ritual Effect Monster', 'Machine', 'DARK', 4, 2000, 2200, '「魔键-马夫提亚」降临。这个卡名的①的效果1回合只能使用1次。 ①：这张卡仪式召唤成功的场合才能发动。从卡组把1张「魔键」卡加入手卡。 ②：1回合1次，持有和自己墓地的通常怪兽或者「魔键」怪兽的其中任意种相同属性的对方怪兽在和这张卡进行战斗的攻击宣言时才能发动。自己手卡任意数量回到卡组最下面，那只对方怪兽的效果直到回合结束时无效。那之后，自己抽出回到卡组的数量。'),
(68300121, 'Magikey Spirit - Vepartu', '魔键凭灵-威沛图', '魔鍵憑霊－ウェパルトゥ', 'XYZ Monster', 'Sea Serpent', 'WATER', 4, 2000, 2000, '4星怪兽×2 ①：这张卡超量召唤成功的场合，把这张卡1个超量素材取除才能发动。从自己的卡组·墓地选1只4星以上的通常怪兽加入手卡。 ②：这张卡有通常怪兽在作为超量素材的场合，得到以下效果。 ●持有和自己墓地的通常怪兽或者「魔键」怪兽的其中任意种相同属性的对方怪兽和这张卡进行战斗的伤害步骤开始时，把这张卡1个超量素材取除才能发动。对方必须把那只怪兽送去墓地。'),
(98904974, 'Magikey Unlocking', '魔键锭-解-', '魔鍵錠－解－', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：「魔键」仪式怪兽或者从额外卡组特殊召唤的「魔键」怪兽在自己场上存在，对方把魔法·陷阱卡发动时才能发动。那个发动无效并破坏。那之后，可以宣言1个属性。那个场合，直到回合结束时对方场上的全部表侧表示怪兽变成宣言的属性。'),
(35815783, 'Magikey World', '魔键施解', '魔鍵施解', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的③的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「魔键」怪兽加入手卡。 ②：只要这张卡在场地区域存在，衍生物以外的自己场上的通常怪兽在1回合各有1次不会被战斗·效果破坏。 ③：自己主要阶段才能发动。从卡组把1张「魔键-马夫提亚」加入手卡。那之后，选1张手卡回到卡组最下面。'),
(31699677, 'Magikuriboh', '魔术库里波', 'マジクリボー', 'Effect Monster', 'Fiend', 'DARK', 1, 300, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：战斗或者对方的效果让自己受到伤害的回合的主要阶段以及战斗阶段，把这张卡从手卡送去墓地才能发动。从自己的卡组·墓地选1只「黑魔术师」或者「黑魔术少女」特殊召唤。这个效果在对方回合也能发动。 ②：自己场上的表侧表示的魔法师族怪兽被战斗或者对方的效果破坏的场合才能发动。墓地的这张卡加入手卡。'),
(15983048, 'Maginificent Magikey Mafteal', '大魔键-马夫提亚尔', '大魔鍵－マフテアル', 'Tuner Monster', 'Fiend', 'LIGHT', 4, 1600, 1600, '这个卡名的②的效果1回合只能使用1次，把这张卡作为同调·超量召唤的素材的场合，不是「魔键」怪兽的同调·超量召唤不能使用。 ①：自己场上有「魔键」怪兽存在的场合，把手卡的这张卡给对方观看才能发动。这个回合，自己在通常召唤外加上只有1次，可以把1只「魔键」怪兽召唤。 ②：这张卡召唤成功时，以自己墓地的4星以下的1只通常怪兽或者「魔键」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(66104644, 'Magister of Endymion', '恩底弥翁之导师', 'マギステル・オブ・エンディミオン', 'Pendulum Effect Monster', 'Spellcaster', 'EARTH', 3, 1500, 900, '自己对「恩底弥翁的统领」1回合只能有1次特殊召唤。 ①：这张卡的攻击宣言时才能发动。给这张卡放置1个魔力指示物。 ②：对方回合1次，把自己场上3个魔力指示物取除才能发动。可以放置魔力指示物的1只怪兽从卡组特殊召唤。 ③：怪兽区域的这张卡被破坏的场合才能发动。这张卡在自己的灵摆区域放置。那之后，这张卡放置过的数量的魔力指示物给这张卡放置。'),
(58270977, 'Magistery Alchemist', '至尊炼金术师', 'マジスタリー・アルケミスト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己墓地以及自己场上的表侧表示怪兽之中把4只「英雄」怪兽除外，以自己墓地1只「英雄」怪兽为对象才能发动。那只怪兽无视召唤条件特殊召唤。把「地」「水」「炎」「风」的全部属性除外发动的场合，这个效果特殊召唤的怪兽的原本攻击力变成2倍，对方场上的全部表侧表示的卡的效果无效化。'),
(66532962, 'Magistus Chorozo', '伟魔精灵 科罗佐', '精霊コロゾ', 'Fusion Monster', 'Spellcaster', 'DARK', 4, 1000, 2800, '融合·同调·超量·连接怪兽＋魔法师族怪兽 这张卡用融合召唤以及以下方法才能从额外卡组特殊召唤。 ●把自己场上1张融合·同调·超量·连接怪兽卡和1张魔法师族怪兽卡送去墓地的场合可以特殊召唤。 ①：1回合1次，自己或对方的怪兽的攻击宣言时，以那1只怪兽为对象才能发动。那次攻击无效，这张卡的攻击力直到回合结束时上升作为对象的怪兽的攻击力数值。那之后，可以让作为对象的怪兽回到手卡。'),
(34933456, 'Magistus Invocation', '伟魔降灵', '聖なる法典', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·场上把融合怪兽卡决定的包含魔法师族怪兽的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。「大贤者」融合怪兽融合召唤的场合，给「大贤者」怪兽装备的自己的魔法与陷阱区域的当作装备卡使用的融合素材怪兽也能作为融合素材使用。'),
(7548747, 'Magistus Theurgy', '伟魔神通', '大いなる魔導', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「大贤者」怪兽为对象才能发动。从自己的额外卡组·场上·墓地选1只4星以外的「大贤者」怪兽当作装备卡使用给作为对象的怪兽装备。自己墓地有「大贤者」融合·同调·超量·连接怪兽各1只以上存在的场合，也能从「大贤者」怪兽以外的额外卡组的融合·同调·超量·连接怪兽中选这个效果装备的怪兽。'),
(327051, 'Magistus Vritra', '伟魔祆现', '絶火の祆現', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地1只4星以下的「大贤者」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：自己的魔法与陷阱区域的「大贤者」卡被对方的效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(95833645, 'Magma Dragon', '岩浆龙', 'マグマ・ドラゴン', 'Effect Monster', 'Wyrm', 'FIRE', 4, 1600, 1200, '「岩浆龙」的效果1回合只能使用1次，这个效果发动的回合，自己不是幻龙族怪兽不能特殊召唤。 ①：这张卡特殊召唤成功时，以「岩浆龙」以外的自己墓地1只幻龙族怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(50951254, 'Magmacho Dragon', '岩浆肌肉龙', 'マグマッチョ・ドラゴン', 'Effect Monster', 'Pyro', 'FIRE', 8, 1800, 2200, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己墓地把最多3只炎属性怪兽除外才能发动。这张卡的攻击力直到回合结束时上升除外数量×400。 ②：这张卡在墓地存在的状态，自己场上的表侧表示的炎属性怪兽被效果破坏的场合才能发动。这张卡特殊召唤。那之后，自己抽1张。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(36750412, 'Magna Drago', '炎龙', '炎龍', 'Tuner Monster', 'Dragon', 'FIRE', 2, 1400, 600, '①：这张卡给与对方战斗伤害的场合发动。这张卡的攻击力上升200。'),
(72903645, 'Magna-Slash Dragon', '巨刃斩龙', 'マグナ・スラッシュドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 6, 2400, 1200, '把自己场上存在的1张表侧表示的永续魔法卡送去墓地。对方场上的1张魔法或者陷阱卡破坏。'),
(26655293, 'Magnarokket Dragon', '麦格农枪弹龙', 'マグナヴァレット・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 4, 1800, 1200, '这个卡名的①②的效果1回合各能使用1次。 ①：场上的这张卡为对象的连接怪兽的效果发动时才能发动。这张卡破坏。那之后，场上1只怪兽送去墓地。 ②：场上的这张卡被战斗·效果破坏送去墓地的回合的结束阶段才能发动。从卡组把「马格努姆弹丸龙」以外的1只「弹丸」怪兽特殊召唤。'),
(65514302, 'Magnet Bonding', '磁石键结', 'マグネット・ボンディング', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己·对方的主要阶段，可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●把1只「超电导战士 线性磁炮王±」或者4星以下的「磁石战士」怪兽从卡组加入手卡。 ●从卡组把1只8星「磁石战士」怪兽加入手卡。 ●自己的手卡·场上·墓地·除外状态的岩石族怪兽作为融合素材回到卡组，把1只岩石族融合怪兽融合召唤。'),
(94940436, 'Magnet Circle LV2', '磁力召唤圆 LV2', '磁力の召喚円 LV２', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从手卡特殊召唤1只2星以下的机械族怪兽。'),
(77133792, 'Magnet Conversion', '磁石转换', 'マグネット・コンバージョン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地最多3只4星以下的「磁石战士」怪兽为对象才能发动。那些怪兽加入手卡。 ②：把墓地的这张卡除外，以除外的1只自己的4星以下的「磁石战士」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果在这张卡送去墓地的回合不能发动。'),
(17841166, 'Magnet Force', '磁石之力', 'マグネット・フォース', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：这个回合，原本种族是机械族或者岩石族的场上的怪兽不受自身以外的对方怪兽的效果影响。'),
(54734082, 'Magnet Induction', '磁石诱导', 'マグネット・インダクション', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有原本等级是4星以下的「磁石战士」怪兽存在的场合才能发动。同名卡不在自己场上存在的1只4星以下的「磁石战士」怪兽从卡组特殊召唤。这张卡的发动后，直到回合结束时自己场上的「磁石战士」怪兽不会被战斗以及对方的效果破坏。'),
(80352158, 'Magnet Reverse', '磁石反转', 'マグネット・リバース', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：从自己墓地的怪兽以及除外的自己怪兽之中以1只机械族·岩石族的不能通常召唤的怪兽为对象才能发动。那只怪兽特殊召唤。'),
(86289475, 'Magnet Warrior Omega Plus', '磁石战士欧米伽＋', '磁石の戦士Ω＋', 'Effect Monster', 'Rock', 'EARTH', 4, 800, 1900, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在的场合才能发动。这张卡以外的自己的手卡·场上（表侧表示）1只岩石族怪兽破坏，这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：场上的地属性怪兽的效果发动时，把这张卡解放，以场上1只表侧表示怪兽为对象才能发动。那只怪兽变成里侧守备表示。'),
(87814728, 'Magnet Warrior Sigma Minus', '磁石战士西格玛－', '磁石の戦士Σ－', 'Effect Monster', 'Rock', 'EARTH', 4, 1500, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡的这张卡给对方观看才能发动。包含手卡的这张卡的自己的手卡·场上的岩石族怪兽作为融合素材，把1只融合怪兽融合召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把1只8星「磁石战士」怪兽送去墓地。 ③：1回合1次，双方的地属性怪兽之间进行战斗的攻击宣言时才能发动。那次攻击无效。'),
(51826619, 'Magnet Warrior Sigma Plus', '磁石战士西格玛＋', '磁石の戦士Σ＋', 'Effect Monster', 'Rock', 'EARTH', 4, 1800, 1500, '这个卡名的③的效果1回合只能使用1次。 ①：只要自己场上有地属性怪兽存在，可以攻击的对方怪兽必须向地属性怪兽作出攻击。 ②：只要对方场上有地属性怪兽存在，对方选择自身怪兽的攻击对象之际，那个攻击对象由自己选择。 ③：这张卡被送去墓地的场合，以除「磁石战士Σ+」外的自己墓地1只4星以下的「磁石战士」怪兽为对象才能发动。那只怪兽加入手卡或特殊召唤。'),
(300302014, 'Magnetic Attraction', NULL, NULL, 'Skill Card', 'Yami Yugi', NULL, NULL, NULL, NULL, NULL),
(4740489, 'Magnetic Field', '磁石力场', 'マグネット・フィールド', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '「磁力场」的①的效果1回合只能使用1次。 ①：自己场上有4星以下的岩石族·地属性怪兽存在的场合，以自己墓地1只4星以下的「磁石战士」怪兽为对象才能把这个效果发动。那只怪兽特殊召唤。 ②：1回合1次，和自己的岩石族·地属性怪兽的战斗没让对方怪兽被破坏的伤害步骤结束时才能发动。那只对方怪兽回到持有者手卡。'),
(50074522, 'Magnetic Mosquito', '电磁蚊', '電磁蚊', 'Flip Effect Monster', 'Insect', 'LIGHT', 3, 300, 1000, '反转：场上表侧表示存在的机械族怪兽全部破坏。'),
(27331568, 'Magnificent Machine Angel', '庄严的机械天使', '荘厳なる機械天使', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己的手卡·场上1只「电子化天使」仪式怪兽解放，以自己场上1只天使族·光属性怪兽为对象才能发动。作为对象的怪兽的攻击力·守备力直到回合结束时上升解放的怪兽的等级×200。这个回合，作为对象的怪兽和从额外卡组特殊召唤的对方怪兽进行战斗的场合，只在战斗阶段内那只对方怪兽的效果无效化。'),
(84877802, 'Magnum Shield', '最强之盾', '最強の盾', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '战士族怪兽才能装备。 ①：装备怪兽的表示形式的以下效果适用。 ●攻击表示：装备怪兽的攻击力上升那个原本守备力数值。 ●守备表示：装备怪兽的守备力上升那个原本攻击力数值。'),
(43227, 'Magnum the Reliever', '后援者・马格南', 'マグナム・ザ・リリーバー', 'Fusion Monster', 'Fiend', 'LIGHT', 8, 2800, 2000, '从额外卡组特殊召唤的怪兽＋手卡的怪兽 这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地1张「融合」魔法卡为对象才能发动。那张卡回到卡组最下面。那之后，自己抽1张。 ②：其他卡的效果发动时，从自己墓地把1张「融合」魔法卡除外，以场上1张卡为对象才能发动。那张卡破坏。'),
(93013676, 'Maha Vailo', '摩诃毗卢', 'マハー・ヴァイロ', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1550, 1400, '①：这张卡的攻击力上升这张卡装备的装备卡数量×500。'),
(45796834, 'Maha Vailo, Light of the Heavens', '光天之摩诃毗卢', '光天のマハー・ヴァイロ', 'Effect Monster', 'Spellcaster', 'LIGHT', 8, 1550, 1400, '①：这张卡得到这张卡的装备卡数量的以下效果。 ●1张以上：这张卡的攻击力上升这张卡的装备卡数量×1000。 ●2张以上：对方在战斗阶段中不能把怪兽的效果发动。 ●3张以上：这张卡为对象的对方的效果发动时，把自己场上1张装备卡送去墓地才能发动。那个效果无效。 ●4张以上：对方在战斗阶段中不能把卡的效果发动。 ●5张以上：这张卡给与对方的战斗伤害变成2倍。'),
(545781, 'Mahaama the Fairy Dragon', '妖龙 摩诃摩', '妖竜マハーマ', 'Tuner Monster', 'Dragon', 'LIGHT', 5, NULL, 2500, '①：对方回合，自己或者对方受到战斗伤害时才能发动。这张卡从手卡特殊召唤。那之后，从以下效果选1个适用。 ●自己基本分回复那次战斗伤害的数值。 ●给与对方那次战斗伤害数值的伤害。'),
(40695128, 'Maharaghi', '磨破罗魏', '磨破羅魏', 'Spirit Monster', 'Rock', 'EARTH', 4, 1200, 1700, '这张卡不能特殊召唤。召唤·反转的回合的结束阶段时回到持有者手卡。此外，这张卡召唤·反转时发动。下次的自己的抽卡阶段的抽卡前把自己卡组最上面的卡确认再回到卡组最上面或者最下面。'),
(53620899, 'Mahjong Munia Maidens', '雀姐妹', '雀姉妹', 'Flip Effect Monster', 'Winged Beast', 'WIND', 2, 200, 2000, '①：自己主要阶段才能发动。这张卡变成里侧守备表示（1回合只有1次）。 ②：这张卡反转的场合才能发动。自己从卡组抽1张，那之后选1张手卡丢弃。'),
(21524779, 'Mahunder', '雷电妈妈', 'OKaサンダー', 'Effect Monster', 'Thunder', 'LIGHT', 4, 1400, 700, '1回合1次，自己的主要阶段时才能发动。从手卡把「雷电妈妈」以外的1只雷族·光属性·4星的怪兽召唤。'),
(8445808, 'Maiden in Love', '恋爱少女', '恋する乙女', 'Effect Monster', 'Spellcaster', 'LIGHT', 2, 400, 300, '①：只要这张卡在怪兽区域存在，可以攻击的对方怪兽必须向这张卡作出攻击。 ②：这张卡不会被战斗破坏。 ③：这张卡和对方怪兽进行战斗的伤害步骤结束时，可以从以下效果选择1个发动。 ●给对方场上1只表侧表示怪兽放置1个少女指示物。 ●得到有少女指示物放置的1只对方怪兽的控制权。'),
(99176254, 'Maiden of Blue Tears', '青泪的少女', '青い涙の乙女', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上有连接怪兽存在，对方把怪兽特殊召唤的场合，以那之内的1只为对象才能发动。那只怪兽破坏，给与对方那个原本攻击力一半数值的伤害。 ②：这张卡在墓地存在的状态，自己或对方受到效果伤害的场合，把这张卡除外，以自己的墓地·除外状态的1张通常魔法卡为对象才能发动。那张卡在自己场上盖放。那张卡在这个回合不能发动。'),
(84055227, 'Maiden of Macabre', '艺妓之影', 'ゲイシャドウ', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1700, NULL, '这张卡战斗破坏对方怪兽的场合，给这张卡放置1个魔力指示物。这张卡的攻击力上升这张卡放置的魔力指示物数量×200的数值。'),
(17214465, 'Maiden of the Aqua', '海神的巫女', '海神の巫女', 'Effect Monster', 'Aqua', 'WATER', 4, 700, 2000, '只要这张卡在场上表侧表示存在，场地变成「海」。场地魔法卡表侧表示存在的场合，这个效果不适用。'),
(37552929, 'Maiden of the Millennium Moon', '千年月辉少女', 'ミレニアムーン・メイデン', 'Effect Monster', 'Illusion', 'LIGHT', 4, 1500, 1300, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合才能发动。这张卡当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。 ②：这张卡是当作永续魔法卡使用的状态，对方的效果发动的场合才能发动。这张卡特殊召唤，这个回合中，对方不能把自己场上的5星以上的幻想魔族·魔法师族怪兽作为效果的对象。 ③：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。'),
(79629370, 'Maiden of the Moonlight', '月明少女', '月明かりの乙女', 'Normal Monster', 'Spellcaster', 'LIGHT', 4, 1500, 1300, '月亮加护的魔导士。神秘的魔法能使人看到幻觉。'),
(17947697, 'Maiden of White', '白之少女', '白き乙女', 'Tuner Monster', 'Spellcaster', 'LIGHT', 1, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：把手卡·场上的这张卡送去墓地才能发动。从自己的手卡·卡组·墓地把1张「真正之光」在自己的魔法与陷阱区域表侧表示放置。 ②：这张卡在墓地存在的状态，自己把「青眼白龙」特殊召唤的场合才能发动。这张卡特殊召唤。 ③：场上的这张卡成为攻击·效果的对象时才能发动。从自己墓地把1只「青眼白龙」或光属性·1星调整特殊召唤。'),
(88241506, 'Maiden with Eyes of Blue', '青之眼少女', '青き眼の乙女', 'Tuner Monster', 'Spellcaster', 'LIGHT', 1, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：场上的表侧表示的这张卡成为效果的对象时才能发动。从自己的手卡·卡组·墓地选1只「青眼白龙」特殊召唤。 ②：这张卡被选择作为攻击对象时才能发动。那次攻击无效，这张卡的表示形式变更。那之后，可以从自己的手卡·卡组·墓地选1只「青眼白龙」特殊召唤。'),
(74983882, 'Maize Token', '小玉米', 'モロコシーナ', 'Token', 'Plant', NULL, NULL, NULL, NULL, NULL),
(5506791, 'Majespecter Cat - Nekomata', '威风魔灵・又猫', 'マジェスペクター・キャット', 'Pendulum Effect Monster', 'Spellcaster', 'WIND', 3, 100, 1800, '「威风妖怪·猫」的①的怪兽效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功时才能发动。这个回合的结束阶段，从卡组把1张「威风妖怪」卡加入手卡。 ②：这张卡只要在怪兽区域存在，不会成为对方的效果的对象，不会被对方的效果破坏。'),
(68395509, 'Majespecter Crow - Yata', '威风魔灵・八咫乌鸦', 'マジェスペクター・クロウ', 'Pendulum Effect Monster', 'Spellcaster', 'WIND', 4, 1000, 1500, '「威风妖怪·乌」的①的怪兽效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功时才能发动。从卡组把1张「威风妖怪」魔法卡加入手卡。 ②：这张卡只要在怪兽区域存在，不会成为对方的效果的对象，不会被对方的效果破坏。'),
(49366157, 'Majespecter Cyclone', '威风魔灵・气旋', 'マジェスペクター・サイクロン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：把自己场上1只魔法师族·风属性怪兽解放，以对方场上1只怪兽为对象才能发动。那只怪兽破坏。'),
(3594985, 'Majespecter Draco - Ryu', '威风魔灵・麒龙', 'マジェスペクター・ドラコ', 'XYZ Pendulum Effect Monster', 'Spellcaster', 'WIND', 4, 2300, 2000, '4星怪兽×2 4星可以灵摆召唤的场合在额外卡组的表侧的这张卡可以灵摆召唤。这个卡名的①的怪兽效果1回合可以使用最多2次。 ①：这张卡在怪兽区域存在的状态，怪兽被解放的场合，把这张卡1个超量素材取除才能发动。从卡组把1只6星以下的魔法师族·风属性怪兽特殊召唤。 ②：怪兽区域的这张卡被战斗·效果破坏的场合或者被解放的场合才能发动。这张卡在自己的灵摆区域放置。'),
(94784213, 'Majespecter Fox - Kyubi', '威风魔灵・九尾狐狸', 'マジェスペクター・フォックス', 'Pendulum Effect Monster', 'Spellcaster', 'WIND', 4, 1500, 1000, '「威风妖怪·狐」的①的怪兽效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功时才能发动。从卡组把1张「威风妖怪」陷阱卡加入手卡。 ②：这张卡只要在怪兽区域存在，不会成为对方的效果的对象，不会被对方的效果破坏。'),
(5153769, 'Majespecter Gust', '威风魔灵・阵风', 'マジェスペクター・ガスト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己的灵摆区域1张「威风妖怪」卡为对象才能发动。那张卡特殊召唤。'),
(66384688, 'Majespecter Orthrus - Nue', '威风魔灵・双头鵺', 'マジェスペクター・オルト', 'Link Monster', 'Spellcaster', 'WIND', NULL, 1500, NULL, '包含「威风妖怪」怪兽的灵摆怪兽2只 这个卡名的效果1回合只能使用1次。 ①：这张卡连接召唤的场合才能发动。从自己的额外卡组（表侧）把最多2只「威风妖怪」灵摆怪兽加入手卡。那之后，可以从卡组把最多2只「威风妖怪」灵摆怪兽表侧加入额外卡组（同名卡最多1张）。这个效果的发动后，直到回合结束时自己不是「威风妖怪」怪兽以及「龙剑士」怪兽不能从额外卡组特殊召唤。'),
(51073802, 'Majespecter Porcupine - Yamarashi', '威风魔灵・山颪豪猪', 'マジェスペクター・ポーキュパイン', 'Pendulum Effect Monster', 'Spellcaster', 'WIND', 4, 1500, 1500, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：自己·对方的主要阶段，自己场上有「威风妖怪」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合，以自己墓地1张「威风妖怪」魔法卡为对象才能发动。那张卡在自己场上盖放。 ③：只要这张卡在怪兽区域存在，这张卡不会被对方的效果破坏，对方不能把这张卡作为效果的对象。'),
(31991800, 'Majespecter Raccoon - Bunbuku', '威风魔灵・分福浣熊', 'マジェスペクター・ラクーン', 'Pendulum Effect Monster', 'Spellcaster', 'WIND', 3, 1200, 900, '这个卡名的①的怪兽效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤时才能发动。从卡组把1只「威风妖怪」怪兽加入手卡。 ②：只要这张卡在怪兽区域存在，这张卡不会被对方的效果破坏，对方不能把这张卡作为效果的对象。'),
(13611090, 'Majespecter Sonics', '威风魔灵・声波', 'マジェスペクター・ソニック', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以自己场上1只「威风妖怪」怪兽为对象才能发动。那只怪兽直到回合结束时攻击力·守备力变成2倍，给与对方的战斗伤害变成一半。'),
(13972452, 'Majespecter Storm', '威风魔灵・风暴', 'マジェスペクター・ストーム', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只魔法师族·风属性怪兽解放，以对方场上1只怪兽为对象才能发动。那只怪兽回到持有者卡组。'),
(78949372, 'Majespecter Supercell', '威风魔灵・超级单体', 'マジェスペクター・スーパーセル', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己的灵摆区域有「威风妖怪」卡存在的场合，这张卡以外的「威风妖怪」卡的自己场上发动的效果的发动和效果不会被无效化。 ②：1回合1次，以自己墓地5张「威风妖怪」卡为对象才能发动。那5张卡加入卡组洗切。那之后，自己从卡组抽1张。'),
(2572890, 'Majespecter Tempest', '威风魔灵・暴风', 'マジェスペクター・テンペスト', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：可以把自己场上1只魔法师族·风属性怪兽解放把以下效果发动。 ●怪兽的效果发动时才能发动。那个发动无效并破坏。 ●自己或者对方把怪兽特殊召唤之际才能发动。那次特殊召唤无效，那些怪兽破坏。'),
(645794, 'Majespecter Toad - Ogama', '威风魔灵・虾蟆蛙', 'マジェスペクター・フロッグ', 'Pendulum Effect Monster', 'Spellcaster', 'WIND', 4, 1300, 500, '「威风妖怪·蛤蟆」的①的怪兽效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功时才能发动。从卡组选1张「威风妖怪」魔法·陷阱卡在自己场上盖放。这个效果盖放的卡在这个回合不能发动。 ②：这张卡只要在怪兽区域存在，不会成为对方的效果的对象，不会被对方的效果破坏。'),
(36183881, 'Majespecter Tornado', '威风魔灵・龙卷', 'マジェスペクター・トルネード', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只魔法师族·风属性怪兽解放，以对方场上1只怪兽为对象才能发动。那只怪兽除外。'),
(31178212, 'Majespecter Unicorn - Kirin', '威风魔灵・独角麒麟', 'マジェスペクター・ユニコーン', 'Pendulum Effect Monster', 'Spellcaster', 'WIND', 6, 2000, 2000, '这个卡名的①的怪兽效果1回合只能使用1次。 ①：自己·对方回合，以自己场上1只灵摆怪兽和对方场上1只怪兽为对象才能发动。那些怪兽回到手卡。 ②：只要这张卡在怪兽区域存在，这张卡不会被对方的效果破坏，对方不能把这张卡作为效果的对象。'),
(51250293, 'Majespecter Wind', '威风魔灵・乘风', 'マジェスペクター・ウィンド', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。这张卡也能把自己场上1只魔法师族·风属性怪兽解放来发动。 ①：从自己的手卡·墓地把1只「威风妖怪」怪兽特殊召唤。把怪兽解放来把这张卡发动的场合，也能作为代替从卡组把1只「威风妖怪」怪兽特殊召唤。'),
(88722973, 'Majester Paladin, the Ascending Dracoslayer', '升龙剑士 威风行者 圣骑', '昇竜剣士マジェスターP', 'XYZ Monster', 'Dragon', 'WIND', 4, 1850, 2000, '4星灵摆怪兽×2 ①：这张卡超量召唤成功时才能发动。这个回合的结束阶段，从卡组把1只灵摆怪兽加入手卡。 ②：1回合1次，把这张卡1个超量素材取除才能发动。从自己的额外卡组把1只表侧表示的「龙剑士」灵摆怪兽特殊召唤。这个效果特殊召唤的怪兽不能作为超量召唤的素材。'),
(63144961, 'Majestic Absorption', '救世吸收', 'セイヴァー・アブソープション', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以以自己场上1只「星尘龙」或者有那个卡名记述的同调怪兽为对象，从以下效果选择1个发动。 ●选对方场上1只表侧表示怪兽，那只怪兽当作装备卡使用给作为对象的自己怪兽装备。 ●这个回合，作为对象的怪兽可以直接攻击。 ●这个回合，每次作为对象的怪兽战斗破坏对方怪兽，给与对方那只破坏的怪兽的原本攻击力数值的伤害。'),
(21159309, 'Majestic Dragon', '救世龙', '救世竜 セイヴァー・ドラゴン', 'Tuner Monster', 'Dragon', 'LIGHT', 1, NULL, NULL, '把这张卡作为同调素材的场合，不是「救世」怪兽的同调召唤不能使用。'),
(95701283, 'Majestic Mech - Goryu', '光神机-轰龙', '光神機－轟龍', 'Effect Monster', 'Fairy', 'LIGHT', 8, 2900, 1800, '这张卡可以用1只祭品作召唤。这个方法召唤的场合，这张卡在结束阶段时送去墓地。此外，这张卡攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(69303178, 'Majestic Mech - Ohka', '光神机-樱火', '光神機－桜火', 'Effect Monster', 'Fairy', 'LIGHT', 6, 2400, 1400, '这张卡可以不用祭品作召唤。这个方法召唤的场合，这张卡在结束阶段时送去墓地。'),
(32918479, 'Majestic Mech - Senku', '光神机-闪空', '光神機－閃空', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1000, 500, '这张卡直接攻击给与对方基本分战斗伤害时，从自己卡组抽1张卡。这张卡在召唤·反转召唤·特殊召唤的回合的结束阶段时，这张卡送去墓地。'),
(98020526, 'Majestic Mirage', '救世幻象', 'セイヴァー・ミラージュ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己场上的表侧表示的「星尘龙」或者有那个卡名记述的同调怪兽为让自己的卡的效果发动而从场上离开的场合或者因自己的卡的效果从场上离开的场合才能发动。从以下效果选1个适用。这个回合，自己的「救世幻象」的效果不能有相同效果适用。 ●选那1只怪兽特殊召唤。 ●从对方的场上·墓地选1只怪兽除外。 ●这个回合，自己受到的全部伤害变成一半。'),
(67030233, 'Majestic Red Dragon', '救世魔龙', 'セイヴァー・デモン・ドラゴン', 'Synchro Monster', 'Dragon', 'DARK', 10, 4000, 3000, '「救世龙」＋「红莲魔龙」＋调整以外的怪兽1只 这张卡不会被卡的效果破坏。这张卡攻击的场合，伤害计算后把场上守备表示存在的怪兽全部破坏。1回合1次，可以直到结束阶段时把对方1只表侧表示怪兽的效果无效，这张卡的攻击力上升那只怪兽的攻击力数值。结束阶段时这张卡回到额外卡组，把自己墓地存在的1只「红莲魔龙」特殊召唤。'),
(7841112, 'Majestic Star Dragon', '救世星龙', 'セイヴァー・スター・ドラゴン', 'Synchro Monster', 'Dragon', 'WIND', 10, 3800, 3000, '「救世龙」＋「星尘龙」＋调整以外的怪兽1只 对方把魔法·陷阱·效果怪兽的效果发动时，可以通过把这张卡解放来让那个发动无效，对方场上的卡全部破坏。1回合1次，可以选择对方场上表侧表示存在的1只怪兽，那个效果直到结束阶段时无效。此外，这个效果无效的怪兽记述的效果在这个回合可以作为这张卡的效果只有1次发动。结束阶段时，这张卡回到额外卡组，选择自己墓地1只「星尘龙」特殊召唤。'),
(91434602, 'Majesty Hyperion', '权威者·许珀里翁', 'マジェスティ・ヒュペリオン', 'Effect Monster', 'Fairy', 'DARK', 8, 2100, 2700, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：这张卡可以把自己的手卡·场上·墓地1只「代行者」怪兽除外，从手卡·墓地特殊召唤。 ②：自己的天使族怪兽的战斗发生的对自己的战斗伤害让对方也承受。 ③：1回合1次，从自己的手卡·墓地把1只天使族怪兽除外，以自己或者对方的墓地1张卡为对象才能发动。那张卡除外。场上或者墓地有「天空的圣域」存在的场合，这个效果1回合可以使用最多2次。'),
(95004025, 'Majesty Maiden, the True Dracocaster', '真龙导士 威风凛凛 少女', '真竜導士マジェスティM', 'Effect Monster', 'Wyrm', 'WIND', 5, 2300, 1500, '这张卡表侧表示上级召唤的场合，可以作为怪兽的代替而把自己场上的永续魔法·永续陷阱卡解放。 ①：这张卡是已上级召唤的场合，1回合1次，对方把魔法·陷阱·怪兽的效果发动时才能发动。从卡组把1只「真龙」怪兽加入手卡。'),
(43219114, 'Majesty of the White Dragons', '白之龙的威光', '白き龍の威光', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：选自己的手卡·场上（表侧表示）·墓地最多3只「青眼白龙」，给双方确认。那之后，确认数量的对方场上的卡破坏。 ②：把墓地的这张卡除外才能发动。等级合计直到变成和仪式召唤的怪兽相同为止，把自己的手卡·场上的「青眼白龙」解放，从手卡把1只仪式怪兽仪式召唤。'),
(92332424, 'Majesty Pegasus, the Dracoslayer', '龙剑士 威风凛凛 天马', '竜剣士マジェスティP', 'Pendulum Effect Monster', 'Spellcaster', 'WIND', 4, 1500, 1500, '这个卡名在规则上也当作「威风妖怪」卡使用。这个卡名的②的怪兽效果1回合只能使用1次。 ①：自己·对方回合，把这张卡从手卡丢弃才能发动。这个回合中，自己场上的「龙剑士」怪兽不会被对方的效果破坏，对方不能把那些作为效果的对象。 ②：这张卡灵摆召唤或者用「龙剑士」卡的效果特殊召唤的场合才能发动。从卡组把1张场地魔法卡加入手卡。那之后，选自己1张手卡丢弃。'),
(2783661, 'Majesty with Eyes of Blue', '青之眼的威光', '青き眼の威光', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡·卡组把1只「青眼」怪兽送去墓地，以场上1只表侧表示怪兽为对象才能发动。那只怪兽只要在场上表侧表示存在不能攻击。'),
(33746252, 'Majesty''s Fiend', '威光魔者', '威光魔人', 'Effect Monster', 'Fiend', 'LIGHT', 6, 2400, 1000, '这张卡不能特殊召唤。只要这张卡在场上表侧表示存在，双方不能把效果怪兽的效果发动。'),
(76473843, 'Majesty''s Pegasus', '威风阵 天马', 'マジェスティックP', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '「威风阵·飞马」的②的效果1回合只能使用1次。 ①：场上的「威风妖怪」怪兽的攻击力·守备力上升300。 ②：把自己场上1只魔法师族·风属性怪兽解放才能发动。从卡组把1只4星以下的「威风妖怪」怪兽特殊召唤。'),
(60102563, 'Maji-Gire Panda', '动真格的熊猫', '本気ギレパンダ', 'Effect Monster', 'Beast', 'EARTH', 4, 1000, 800, '只要这张卡在自己场上表侧表示存在，每次场上的兽族怪兽被破坏，这张卡攻击力上升500。'),
(67211766, 'Majioshaleon', '真文色龙', 'マジオシャレオン', 'Effect Monster', 'Reptile', 'WATER', 5, 2000, 800, '只要对方场上有魔法·陷阱卡存在，对方不能选择这张卡作为攻击对象。此外，这张卡向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(59951714, 'Majiosheldon', '上级献身者', 'アドバンス・ディボーター', 'Effect Monster', 'Warrior', 'WATER', 3, 800, 2000, '这张卡不用这张卡的效果不能特殊召唤。把这张卡解放作上级召唤成功的场合，下次的自己的准备阶段时才能发动。这张卡从墓地特殊召唤。这个效果发动的回合，自己不能从额外卡组把怪兽特殊召唤。'),
(9074847, 'Major Riot', '大骚动', '大騒動', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己的怪兽被对方控制的卡的效果从场地回到手卡时才能发动。场上的全部怪兽回到持有者手卡。那之后，双方从手卡把回去数量的怪兽里侧守备表示特殊召唤。'),
(8794435, 'Maju Garzett', '合成魔兽 加泽特', '合成魔獣 ガーゼット', 'Effect Monster', 'Fiend', 'DARK', 7, -1, NULL, '这张卡的攻击力变成祭品召唤时作为祭品的2只怪兽的原本攻击力合计的数值。'),
(27827272, 'Makiu, the Magical Mist', '魔雾雨', '魔霧雨', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己不能进行战斗阶段。 ①：以自己的怪兽区域1只「恶魔召唤」或者雷族怪兽为对象才能发动。持有那只怪兽的攻击力以下的守备力的对方场上的怪兽全部破坏。'),
(21593977, 'Makyura the Destructor', '处刑人-摩休罗', '処刑人－マキュラ', 'Effect Monster', 'Warrior', 'DARK', 4, 1600, 1200, '这个卡名的效果1回合只能使用1次。 ①：这张卡从怪兽区域送去墓地的场合才能发动。这个回合只有1次，自己可以把陷阱卡从手卡发动。'),
(35330871, 'Malacoda, Netherlord of the Burning Abyss', '彼岸鬼神 赫尔雷卡', '彼岸の鬼神 ヘルレイカー', 'Ritual Effect Monster', 'Fiend', 'DARK', 6, 2700, 2200, '「善恶的彼岸」降临。这张卡不用仪式召唤不能特殊召唤。 ①：1回合1次，从手卡把1只「彼岸」怪兽送去墓地，以对方场上1只表侧表示怪兽为对象才能发动。那只对方怪兽的攻击力·守备力直到回合结束时下降因为这个效果发动而送去墓地的怪兽的各自数值。这个效果在对方回合也能发动。 ②：这张卡从场上送去墓地的场合，以场上1张卡为对象才能发动。那张卡送去墓地。'),
(9433350, 'Malefic Blue-Eyes White Dragon', 'Sin 青眼白龙', 'Sin 青眼の白龍', 'Effect Monster', 'Dragon', 'DARK', 8, 3000, 2500, '这张卡不能通常召唤。从卡组把1只「青眼白龙」除外的场合可以特殊召唤。 ①：「罪」怪兽在场上只能有1只表侧表示存在。 ②：只要这张卡在怪兽区域存在，其他的自己怪兽不能攻击宣言。 ③：没有场地魔法卡表侧表示存在的场合这张卡破坏。'),
(53063039, 'Malefic Claw Stream', 'Sin 痛怖烈爪', 'Sin Claw Stream', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有「罪」怪兽存在的场合，以对方场上1只怪兽为对象才能发动。那只对方怪兽破坏。'),
(1710476, 'Malefic Cyber End Dragon', 'Sin 电子终极龙', 'Sin サイバー・エンド・ドラゴン', 'Effect Monster', 'Machine', 'DARK', 10, 4000, 2800, '这张卡不能通常召唤。从额外卡组把1只「电子终结龙」除外的场合才能特殊召唤。 ①：「罪」怪兽在场上只能有1只表侧表示存在。 ②：只要这张卡在怪兽区域存在，其他的自己怪兽不能攻击宣言。 ③：没有场地魔法卡表侧表示存在的场合这张卡破坏。'),
(81384993, 'Malefic Divide', 'Sin 痛怖交错', 'Sin Cross', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以自己墓地1只「罪」怪兽为对象才能发动。那只怪兽无视召唤条件特殊召唤。这个效果特殊召唤的怪兽的效果无效化，结束阶段除外。'),
(16958382, 'Malefic Paradigm Dragon', 'Sin 范式龙', 'Sin パラダイム・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 10, 4000, 4000, '这张卡不能通常召唤。场上没有「罪 范式龙」存在的场合，从额外卡组把1只「罪」怪兽除外的场合才能特殊召唤。 ①：场上没有「罪 世界」存在的场合这张卡破坏。 ②：1回合1次，从卡组把1张「罪」卡送去墓地才能发动。除外的1只自己的8星同调怪兽回到额外卡组。那之后，可以把那只怪兽从额外卡组特殊召唤。这个回合，自己不用「罪」怪兽不能攻击。'),
(8310162, 'Malefic Paradox Dragon', 'Sin 悖论龙', 'Sin パラドクス・ドラゴン', 'Synchro Monster', 'Dragon', 'DARK', 10, 4000, 4000, '「罪 平行齿轮」＋调整以外的「罪」怪兽1只 ①：「罪 矛盾龙」在场上只能有1只表侧表示存在。 ②：这张卡同调召唤成功时，以自己或者对方的墓地1只同调怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。 ③：场上没有「罪 世界」存在的场合这张卡破坏。'),
(48829461, 'Malefic Paradox Gear', 'Sin 悖论齿轮', 'Sin パラドクスギア', 'Effect Monster', 'Machine', 'DARK', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：场地魔法卡表侧表示存在的场合，把这张卡解放才能发动。从卡组把1只「罪 平行齿轮」特殊召唤。那之后，从卡组把「罪 矛盾齿轮」以外的1只「罪」怪兽加入手卡。 ②：为让自己手卡的「罪」怪兽用自身的方法特殊召唤而把怪兽除外的场合，可以作为那怪兽的代替而把场上·墓地的这张卡除外。'),
(74509280, 'Malefic Parallel Gear', 'Sin 平行齿轮', 'Sin パラレルギア', 'Tuner Monster', 'Machine', 'DARK', 2, NULL, NULL, '把这张卡作为同调素材的场合，其他的同调素材怪兽必须是手卡1只「罪」怪兽。'),
(598988, 'Malefic Rainbow Dragon', 'Sin 彩虹龙', 'Sin レインボー・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 10, 4000, NULL, '这张卡不能通常召唤。从手卡·卡组把1只「究极宝玉神 虹龙」除外的场合才能特殊召唤。 ①：「罪」怪兽在场上只能有1只表侧表示存在。 ②：只要这张卡在怪兽区域存在，其他的自己怪兽不能攻击宣言。 ③：没有场地魔法卡表侧表示存在的场合这张卡破坏。'),
(55343236, 'Malefic Red-Eyes Black Dragon', 'Sin 真红眼黑龙', 'Sin 真紅眼の黒竜', 'Effect Monster', 'Dragon', 'DARK', 7, 2400, 2000, '这张卡不能通常召唤。从卡组把1只「真红眼黑龙」除外的场合可以特殊召唤。 ①：「罪」怪兽在场上只能有1只表侧表示存在。 ②：只要这张卡在怪兽区域存在，其他的自己怪兽不能攻击宣言。 ③：没有场地魔法卡表侧表示存在的场合这张卡破坏。'),
(18378992, 'Malefic Selector', 'Sin 选择者', 'Sin Selector', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己墓地把2张「罪」卡除外才能发动。和除外的卡卡名不同的「罪 选择」以外的2张「罪」卡从卡组加入手卡（同名卡最多1张）。'),
(36521459, 'Malefic Stardust Dragon', 'Sin 星尘龙', 'Sin スターダスト・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 8, 2500, 2000, '这张卡不能通常召唤。从额外卡组把1只「星尘龙」除外的场合才能特殊召唤。 ①：「罪」怪兽在场上只能有1只表侧表示存在。 ②：只要这张卡在怪兽区域存在，场地区域的表侧表示的卡不会被效果破坏。 ③：只要这张卡在怪兽区域存在，其他的自己怪兽不能攻击宣言。 ④：没有场地魔法卡表侧表示存在的场合这张卡破坏。'),
(75223115, 'Malefic Territory', 'Sin 领域', 'Sin Territory', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：作为这张卡的发动时的效果处理，可以从卡组把1张「罪 世界」发动。只要这个效果发动的卡在场地区域存在，双方不能把场地区域的卡作为效果的对象。 ②：「罪」怪兽持有的「「罪」怪兽在场上只能有1只表侧表示存在」效果作为「「罪」怪兽每1种类在场上只能有1只表侧表示存在」适用。 ③：只在战斗阶段内场上的「罪」怪兽的效果无效化。'),
(37115575, 'Malefic Truth Dragon', 'Sin 真实龙', 'Sin トゥルース・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 12, 5000, 5000, '这张卡不能通常召唤，用这张卡的效果才能特殊召唤。 ①：「罪 真实龙」以外的自己场上的表侧表示的「罪」怪兽被战斗·效果破坏的场合，把基本分支付一半才能发动。这张卡从手卡·墓地特殊召唤。 ②：「罪」怪兽在场上只能有1只表侧表示存在。 ③：没有场地魔法卡表侧表示存在的场合这张卡破坏。 ④：这张卡战斗破坏对方怪兽的场合发动。对方场上的表侧表示怪兽全部破坏。'),
(44763696, 'Malefic Tune', 'Sin 邪调', 'Sin Tune', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的表侧表示的「罪」怪兽被战斗或者对方的效果破坏的场合才能发动。自己从卡组抽2张。 ②：这张卡在墓地存在的状态，自己场上的表侧表示的「罪」怪兽被战斗以外破坏的场合，把墓地的这张卡除外才能发动。从卡组把1只「罪」怪兽加入手卡。'),
(27564031, 'Malefic World', 'Sin 世界', 'Sin World', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己抽卡阶段作为进行通常抽卡的代替才能发动。从卡组把3张「罪」卡给对方观看，对方从那之中随机选1张。那1张卡加入自己手卡，剩下的卡回到卡组。'),
(1224927, 'Malevolent Catastrophe', '邪神之大灾害', '邪神の大災害', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时才能发动。场上的魔法·陷阱卡全部破坏。'),
(31571902, 'Malevolent Mech - Goku En', '邪神机-狱炎', '邪神機－獄炎', 'Effect Monster', 'Zombie', 'LIGHT', 6, 2400, 1400, '①：这张卡可以不用解放作召唤。 ②：这张卡的①的方法召唤的场合，结束阶段发动。这张卡送去墓地。那之后，自己受到这张卡的原本攻击力数值的伤害。这个效果在场上没有这张卡以外的不死族怪兽存在的场合进行发动和处理。'),
(99597615, 'Malevolent Nuzzler', '恶魔之吻', '悪魔のくちづけ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：装备怪兽的攻击力上升700。 ②：这张卡从场上送去墓地时，支付500基本分才能发动。这张卡回到卡组最上面。'),
(6137095, 'Malfunction', '误作动', '誤作動', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '支付500基本分。陷阱卡的发动无效，那张卡按原本的形式放回。'),
(14255590, 'Malice Ascendant', '增幅的恶意', '増幅する悪意', 'Effect Monster', 'Zombie', 'DARK', 4, 700, 1000, '只要这张卡在场上表侧表示存在，对方回合的准备阶段时自己墓地存在的「增幅的恶意」的数量的对方卡组最上面的卡送去墓地。'),
(13626450, 'Malice Dispersion', '邪气退散', '邪気退散', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '丢弃1张手卡。场上表侧表示存在的永续陷阱卡全部破坏。'),
(72657739, 'Malice Doll of Demise', '怨念之杀人人偶', '怨念のキラードール', 'Effect Monster', 'Fiend', 'DARK', 4, 1600, 1700, '这张卡因永续魔法的效果从场上送去墓地的场合，自己的回合的准备阶段时从墓地特殊召唤。'),
(25643346, 'Malice, Lady of Lament', '恶之魔娘 玛丽斯', '悪魔嬢マリス', 'Effect Monster', 'Fiend', 'DARK', 3, 1000, 1000, '这个卡名的效果1回合只能使用1次。 ①：把自己场上2只怪兽解放，从自己墓地的卡以及除外的自己的卡之中以1张通常陷阱卡为对象才能发动。那张卡在自己场上盖放。这个效果盖放的卡从场上离开的场合回到持有者卡组最下面。这个效果在对方回合也能发动。'),
(61791132, 'Malicevorous Fork', '食恶餐叉鬼', 'マリスボラス・フォーク', 'Effect Monster', 'Fiend', 'DARK', 2, 400, 400, '自己的主要阶段时，从手卡把这张卡以外的1只恶魔族怪兽送去墓地才能发动。这张卡从手卡特殊召唤。'),
(98780137, 'Malicevorous Knife', '食恶餐刀鬼', 'マリスボラス・ナイフ', 'Effect Monster', 'Fiend', 'DARK', 2, 600, 100, '这张卡召唤成功时，可以从自己墓地选择「食恶餐刀鬼」以外的1只名字带有「食恶」的怪兽特殊召唤。'),
(35307484, 'Malicevorous Spoon', '食恶餐匙鬼', 'マリスボラス・スプーン', 'Effect Monster', 'Fiend', 'DARK', 2, 100, 500, '这张卡在场上表侧表示存在的场合「食恶餐匙鬼」以外的名字带有「食恶」的怪兽在自己场上召唤·特殊召唤时，可以从自己墓地选择1只恶魔族·2星怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。「食恶餐匙鬼」的效果1回合只能使用1次。'),
(96676583, 'Maliss Chessy Cat', '码丽丝＜兵＞柴郡猫', 'M∀LICE＜P＞Cheshire Cat', 'Effect Monster', 'Cyberse', 'DARK', 3, 1500, 300, '这个卡名的①③的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从手卡选1张「码丽丝」卡除外。那之后，自己可以抽2张。 ②：有这张卡位于所连接区的「码丽丝」连接怪兽战斗破坏的怪兽不去墓地而除外。 ③：这张卡被除外的场合，支付300基本分才能发动。这张卡特殊召唤。这个回合，自己不是连接怪兽不能从额外卡组特殊召唤。'),
(32061192, 'Maliss Dormouse', '码丽丝＜兵＞睡鼠', 'M∀LICE＜P＞Dormouse', 'Effect Monster', 'Cyberse', 'DARK', 3, 900, 300, '这个卡名的①③的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从卡组把1只「码丽丝」怪兽除外。这个回合中自己场上的「码丽丝」怪兽的攻击力上升600。 ②：有这张卡位于所连接区的「码丽丝」连接怪兽不会被效果破坏。 ③：这张卡被除外的场合，支付300基本分才能发动。这张卡特殊召唤。这个回合，自己不是连接怪兽不能从额外卡组特殊召唤。'),
(20726052, 'Maliss GWC-06', '码丽丝＜序＞GWC－06', 'M∀LICE＜C＞GWC－０６', 'Trap Card', '', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。这张卡也能把自己场上1只表侧表示的「码丽丝」怪兽除外，在盖放的回合发动。 ①：自己的墓地·除外状态的1只「码丽丝」怪兽特殊召唤。那之后，自己场上有「码丽丝」连接怪兽存在的场合，可以让自己基本分回复这个效果特殊召唤的怪兽的原本攻击力的数值。'),
(21848500, 'Maliss Hearts Crypter', '码丽丝＜后＞红心密匿', 'M∀LICE＜Q＞HEARTS OF CRYPTER', 'Link Monster', 'Cyberse', 'DARK', NULL, 2500, NULL, '包含「码丽丝」怪兽的怪兽3只 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合，以自己的除外状态的1张「码丽丝」卡为对象才能发动（这张卡所连接区有怪兽存在的场合，这个发动和这个效果不会被无效化）。那张卡回到卡组，场上1张卡除外。 ②：这张卡被除外的场合，支付900基本分才能发动。这张卡的攻击力变成2倍特殊召唤。'),
(93453053, 'Maliss in the Mirror', '码丽丝镜中奇缘', 'M∀LICE IN THE MIRROR', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以对方场上1只表侧表示怪兽为对象才能发动。从自己的手卡·场上（表侧表示）把1只「码丽丝」怪兽除外，作为对象的怪兽的效果直到回合结束时无效。 ②：这张卡被除外的场合，以自己墓地1张「码丽丝」卡为对象才能发动。那张卡除外，和除外的卡相同种类（怪兽·魔法·陷阱）的1张「码丽丝」卡从卡组加入手卡。'),
(68337209, 'Maliss in Underground', '码丽丝梦游深界', 'M∀LICE IN UNDERGROUND', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从自己的手卡·卡组·墓地把1张「码丽丝」卡除外。 ②：只要自己的除外状态的「码丽丝」陷阱卡3种类以上存在，自己场上的「码丽丝」连接怪兽的攻击力上升3000。 ③：只要自己场上有「码丽丝」连接怪兽存在，对方怪兽只能选择「码丽丝」连接怪兽作为攻击对象。'),
(20938824, 'Maliss March Hare', '码丽丝＜兵＞三月兔', 'M∀LICE＜P＞March Hare', 'Effect Monster', 'Cyberse', 'DARK', 3, 600, 300, '这个卡名的①③的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，自己·对方的主要阶段才能发动。从自己的手卡·墓地把这张卡以外的1张「码丽丝」卡除外，这张卡特殊召唤。 ②：对方不能把有这张卡位于所连接区的「码丽丝」连接怪兽作为效果的对象。 ③：这张卡被除外的场合，支付300基本分，以自己的除外状态的1只「码丽丝」怪兽为对象才能发动。那只怪兽加入手卡。'),
(94722358, 'Maliss MTP-07', '码丽丝＜序＞MTP－07', 'M∀LICE＜C＞MTP－０７', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。这张卡也能把自己场上1只表侧表示的「码丽丝」怪兽除外，在盖放的回合发动。 ①：从卡组把1只「码丽丝」怪兽加入手卡。自己场上有「码丽丝」连接怪兽存在的场合，可以再把场上1张卡除外。'),
(68059897, 'Maliss Red Ransom', '码丽丝＜后＞赤色勒赎', 'M∀LICE＜Q＞RED RANSOM', 'Link Monster', 'Cyberse', 'DARK', NULL, 2300, NULL, '包含「码丽丝」怪兽的怪兽2只以上 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。从卡组把1张「码丽丝」魔法卡加入手卡。 ②：只要这张卡所连接区有怪兽存在，对方场上的效果怪兽的原本攻击力和原本守备力交换。 ③：这张卡被除外的场合，支付900基本分才能发动。这张卡特殊召唤。那之后，可以从卡组把1只电子界族怪兽除外。'),
(57111661, 'Maliss TB-11', '码丽丝＜序＞TB－11', 'M∀LICE＜C＞TB－１１', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。这张卡也能把自己场上1只表侧表示的「码丽丝」怪兽除外，在盖放的回合发动。 ①：从卡组把1只「码丽丝」怪兽特殊召唤。对方场上有卡3张以上存在的场合，也能作为代替从额外卡组把1只「码丽丝」连接怪兽特殊召唤。这个回合，这个效果特殊召唤的怪兽不能攻击，那个效果不能发动。'),
(95454996, 'Maliss White Binder', '码丽丝＜后＞白色绑缚', 'M∀LICE＜Q＞WHITE BINDER', 'Link Monster', 'Cyberse', 'DARK', NULL, 2300, NULL, '包含「码丽丝」怪兽的怪兽2只以上 这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合，以自己·对方的墓地的卡合计最多3张为对象才能发动。那些卡除外。 ②：自己主要阶段才能发动。从自己的卡组·墓地把1张「码丽丝」陷阱卡在自己场上盖放。 ③：这张卡被除外的场合，支付900基本分才能发动。这张卡特殊召唤。那之后，自己可以抽1张。'),
(69272449, 'Maliss White Rabbit', '码丽丝＜兵＞白兔', 'M∀LICE＜P＞White Rabbit', 'Effect Monster', 'Cyberse', 'DARK', 3, 1200, 300, '这个卡名的①③的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。同名卡不在自己墓地存在的1张「码丽丝」陷阱卡从卡组到自己场上盖放。 ②：有这张卡位于所连接区的「码丽丝」连接怪兽的战斗发生的对自己的战斗伤害变成0。 ③：这张卡被除外的场合，支付300基本分才能发动。这张卡特殊召唤。这个回合，自己不是连接怪兽不能从额外卡组特殊召唤。'),
(42671152, 'Malus Token', '弗丽嘉的苹果', 'フリッグのリンゴ', 'Token', 'Fiend', NULL, NULL, NULL, NULL, NULL),
(83828288, 'Mamemaki', '撒豆', '豆まき', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以对方场上1只表侧表示怪兽为对象才能发动。选那只怪兽的等级数量的自己手卡丢弃，自己从卡组抽出丢弃的数量。那之后，作为对象的怪兽回到持有者手卡。'),
(40374923, 'Mammoth Graveyard', '猛犸的墓场', 'マンモスの墓場', 'Normal Monster', 'Dinosaur', 'EARTH', 3, 1200, 800, '守护着伙伴墓地的猛犸，对于任何胆敢践踏墓地的盗墓者进行毫不客气的攻击。'),
(40680521, 'Mamonaka the Vaylantz United', '弈勇之聚－幻中', 'ヴァリアンツの聚－幻中', 'Pendulum Effect Fusion Monster', 'Spellcaster', 'WATER', 10, 2800, 2800, '「群豪」怪兽×3 这个卡名的①的怪兽效果1回合只能使用1次。 ①：双方的主要阶段，以对方的主要怪兽区域1只效果怪兽为对象才能发动。那只对方怪兽在和那只是相同纵列的对方的魔法与陷阱区域当作永续魔法卡使用以表侧表示放置（所要放置区的卡破坏，那是怪兽卡的场合，对方失去那个攻击力数值的基本分）。 ②：特殊召唤的这张卡被对方的效果破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(71395725, 'Man Beast of Ares', '兽人 阿瑞斯', '獣人アレス', 'Effect Monster', 'Beast-Warrior', 'EARTH', 3, 500, 500, '只要这张卡在场上表侧表示存在，每次有连锁发生这张卡的攻击力上升500。'),
(93553943, 'Man Eater', '食人花', 'マンイーター', 'Normal Monster', 'Plant', 'EARTH', 2, 800, 600, '吃人的人面花，用有毒的触手进行攻击。'),
(54652250, 'Man-Eater Bug', '食人虫', '人喰い虫', 'Flip Effect Monster', 'Insect', 'EARTH', 2, 450, 600, '①：这张卡反转的场合，以场上1只怪兽为对象发动。那只怪兽破坏。'),
(80727036, 'Man-Eating Black Shark', '黑色食人鲛', '黒き人食い鮫', 'Fusion Monster', 'Fish', 'WATER', 5, 2100, 1300, '「深海切割手」＋「杀人污泥」＋「海原的女战士」'),
(49127943, 'Man-Eating Plant', '食人植物', '人喰い植物', 'Normal Monster', 'Plant', 'EARTH', 2, 800, 600, '食肉花。让人觉得是漂亮的花，然后猛地一口吃掉接近它的人。'),
(13723605, 'Man-Eating Treasure Chest', '食人宝石箱', '人喰い宝石箱', 'Normal Monster', 'Fiend', 'DARK', 4, 1600, 1000, '宝石箱形状的怪兽，欺骗冒险者接近并发动攻击。'),
(43714890, 'Man-Thro'' Tro''', '投人的巨魔', '人投げトロール', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 1000, 1000, '每祭掉自己场上1只通常怪兽（衍生物除外），给与对方基本分800分的伤害。'),
(11074235, 'Mana Dragon Zirnitron', '魔晶龙吉鲁德拉斯', '魔晶龍ジルドラス', 'Effect Monster', 'Dragon', 'DARK', 6, 2200, 1200, '这个卡名的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在，自己场上的魔法·陷阱卡因对方的效果从场上离开，被送去墓地的场合或者被除外的场合才能发动。这张卡特殊召唤。那之后，可以从自己墓地的卡以及除外的自己的卡之中选1张魔法·陷阱卡在自己的魔法与陷阱区域盖放。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(19474136, 'Mandragon', '曼陀铃草龙', 'マンドラゴン', 'Pendulum Normal Monster', 'Plant', 'EARTH', 5, 2500, 1000, '宿有充满悲哀龙魂的曼陀林。据说会奏起诅咒的音色，使听者过于恐惧而丧失自我。'),
(38369349, 'Manga Ryu-Ran', '卡通蛋龙', 'トゥーン・ドラゴン・エッガー', 'Toon Monster', 'Dragon', 'FIRE', 7, 2200, 2600, '这张卡不能通常召唤。自己场上有「卡通世界」存在，把自己场上2只怪兽解放的场合可以特殊召唤。 ①：这张卡在特殊召唤的回合不能攻击。 ②：这张卡的攻击宣言之际，自己必须支付500基本分。 ③：对方场上没有卡通怪兽存在的场合，这张卡可以直接攻击。存在的场合，必须把卡通怪兽作为攻击对象。 ④：场上的「卡通世界」被破坏时这张卡破坏。'),
(33455338, 'Maniacal Servant', '邪狂神的使者', '邪狂神の使い', 'Effect Monster', 'Spellcaster', 'DARK', 3, 600, 1000, '对方的准备阶段时只有1次，可以把自己墓地存在的暗属性怪兽任意数量从游戏中除外。直到结束阶段时，这张卡的守备力上升这个效果除外的怪兽数量×500的数值。'),
(95492061, 'Manju of the Ten Thousand Hands', '万手之神', 'マンジュ・ゴッド', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1400, 1000, '①：这张卡召唤·反转召唤时才能发动。从卡组把1只仪式怪兽或1张仪式魔法卡加入手卡。'),
(45065541, 'Mannadium Abscission', '玛那桃圆乡・摘心', '伍世壊摘心', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只怪兽为对象才能发动。那只怪兽破坏，从卡组把1张「伍世坏-喜悦世界」加入手卡。自己场上有「伍世坏-喜悦世界」存在的场合，也能作为代替把「伍世坏摘心」以外的1张「末那愚子族」魔法·陷阱卡加入手卡。 ②：把墓地的这张卡除外才能发动。从手卡把1只「维萨斯-斯塔弗罗斯特」或者攻击力1500/守备力2100的怪兽特殊召唤。'),
(71164684, 'Mannadium Breakheart', '玛那桃圆乡・碎心', '伍世壊砕心', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地1只调整或者同调怪兽为对象才能发动。那只怪兽特殊召唤。这个效果把光属性怪兽特殊召唤的场合，可以再选持有那个攻击力以下的攻击力的对方场上1只怪兽破坏。 ②：自己场上的「维萨斯-斯塔弗罗斯特」或者攻击力1500/守备力2100的怪兽被战斗·效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(17272964, 'Mannadium Fearless', '玛那桃圆乡・无畏', 'マナドゥム・ヒアレス', 'Tuner Monster', 'Fairy', 'EARTH', 2, NULL, 2000, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：自己场上有「维萨斯-斯塔弗罗斯特」或者攻击力1500/守备力2100的怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡被战斗·效果破坏的场合才能发动。从卡组把1只「末那愚子族·小无畏」特殊召唤。这个效果发动的回合的战斗阶段中，自己场上的同调怪兽的攻击力上升500。'),
(19671433, 'Mannadium Imaginings', '玛那桃圆乡・心像', '伍世壊心像', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡1只「末那愚子族」怪兽或者「维萨斯-斯塔弗罗斯特」给对方观看才能发动。自己从卡组抽2张。那之后，选1张手卡回到卡组最下面。 ②：把墓地的这张卡除外，以自己场上1只攻击力1500/守备力2100的怪兽为对象才能发动。那只怪兽直到回合结束时当作调整使用。'),
(44760562, 'Mannadium Meek', '玛那桃圆乡・温顺', 'マナドゥム・ミーク', 'Tuner Monster', 'Fairy', 'WATER', 2, NULL, 1800, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：自己场上有「维萨斯-斯塔弗罗斯特」或者攻击力1500/守备力2100的怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡被战斗·效果破坏的场合才能发动。从卡组把1只「末那愚子族·小温顺」特殊召唤。那之后，可以让这个效果特殊召唤的怪兽的等级上升2星。'),
(90465153, 'Mannadium Prime-Heart', '玛那桃圆乡・普莱姆哈忒', 'マナドゥム・プライムハート', 'Synchro Monster', 'Fairy', 'LIGHT', 10, 3000, 3000, '调整1只以上＋光属性怪兽1只 ①：同调召唤的这张卡在同1次的战斗阶段中可以作出最多有那些作为同调素材的调整数量的攻击。 ②：对方不能把用「末那愚子族」调整为素材作同调召唤的这张卡作为效果的对象。 ③：同调召唤的表侧表示的这张卡因对方从场上离开的场合才能发动。自己的墓地·除外状态的1只「维萨斯-斯塔弗罗斯特」或者攻击力1500/守备力2100的怪兽特殊召唤。'),
(18158393, 'Mannadium Reframing', '玛那桃圆乡・净心', '伍世壊浄心', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有同调怪兽存在，怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效。自己的场上或者墓地有「维萨斯-斯塔弗罗斯特」或者攻击力1500/守备力2100的怪兽存在的场合，可以再把那张无效的卡破坏。 ②：把墓地的这张卡除外，以自己墓地最多3只「末那愚子族」怪兽为对象才能发动。那些怪兽回到卡组。'),
(71277255, 'Mannadium Riumheart', '玛那桃圆乡・里姆哈忒', 'マナドゥム・リウムハート', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1500, 2100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，自己·对方的主要阶段，以自己场上1只「末那愚子族」怪兽或者攻击力1500/守备力2100的怪兽为对象才能发动。那只怪兽破坏，这张卡特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「末那愚子族·里姆哈特」以外的1张「末那愚子族」卡加入手卡。'),
(80621253, 'Mannadium Torrid', '玛那桃圆乡・热情', 'マナドゥム・トリッド', 'Tuner Monster', 'Fairy', 'FIRE', 2, NULL, 1500, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有「维萨斯-斯塔弗罗斯特」或者攻击力1500/守备力2100的怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡被战斗·效果破坏的场合才能发动。从卡组把1只「末那愚子族」调整特殊召唤。'),
(21368273, 'Mannadium Trisukta', '玛那桃圆乡・多利洛斯歌都', 'マナドゥム・トリロスークタ', 'Synchro Tuner Monster', 'Fairy', 'LIGHT', 6, 2300, 1200, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合，以自己墓地1只2星调整为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。 ②：以自己场上的调整任意数量为对象才能发动。那些怪兽的等级变成2星。这个回合，自己不是同调怪兽不能从额外卡组特殊召唤。'),
(36890111, 'Mansion of the Dreadful Dolls', '地狱人偶之馆', '地獄人形の館', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「机关傀儡」怪兽加入手卡。 ②：自己场上的「机关傀儡」怪兽不会被战斗破坏，不受超量怪兽以外的对方怪兽发动的效果影响。 ③：1回合1次，把自己场上1个超量素材取除，以自己墓地1只「机关傀儡」怪兽为对象才能发动。那只怪兽在对方场上守备表示特殊召唤。'),
(77121851, 'Manticore of Darkness', '暗黑之蝎尾狮', '暗黒のマンティコア', 'Effect Monster', 'Beast-Warrior', 'FIRE', 6, 2300, 1000, '这张卡被送去墓地的回合的结束阶段时，从自己的手卡·场上把1只兽族·兽战士族·鸟兽族怪兽送去墓地才能发动。这张卡从墓地特殊召唤。'),
(64538914, 'Manticore of Smashing', '震天之蝎尾狮', '震天のマンティコア', 'Effect Monster', 'Beast-Warrior', 'FIRE', 6, 2300, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从卡组把1张「地割」或者「地碎」加入手卡。 ②：这张卡在墓地存在的场合，从自己的手卡·墓地把1张「地割」或者「地碎」除外才能发动。这张卡特殊召唤。'),
(22916418, 'Mantman the Ultrahuman', '超人传-幔特曼', '超人伝－マントマン', 'Effect Monster', 'Psychic', 'LIGHT', 7, 2400, 1200, '这个卡名的①③的效果1回合各能使用1次。 ①：原本持有者是自己的表侧表示卡在对方场上存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡只要在怪兽区域存在，不能解放，不会被战斗破坏。 ③：这张卡召唤·特殊召唤的回合的结束阶段才能发动。这张卡回到卡组最下面。那之后，可以让原本持有者是自己的场上1张表侧表示卡回到手卡。'),
(73104892, 'Maple Maiden', '伊吕波红叶', 'いろはもみじ', 'Synchro Monster', 'Fairy', 'WIND', 7, 2100, 2600, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合，宣言1个属性才能发动。这张卡得到以下效果。 ●场上的全部表侧表示怪兽变成宣言的属性。 ②：以对方的主要怪兽区域1只怪兽为对象才能发动。对方必须从那只怪兽的前面·后面·相邻的区域（怪兽区域·魔法与陷阱区域）存在的卡之中把1张送去墓地。'),
(73417207, 'Mara of the Nordic Alfar', '极星灵 黑精灵', '極星霊スヴァルトアールヴ', 'Tuner Monster', 'Spellcaster', 'DARK', 2, 1000, 500, '把这张卡作为同调素材的场合，其他的同调素材怪兽必须是手卡2只名字带有「极星」的怪兽。'),
(2460565, 'Marauding Captain', '冲锋陷阵的队长', '切り込み隊長', 'Effect Monster', 'Warrior', 'EARTH', 3, 1200, 400, '①：这张卡召唤成功时才能发动。从手卡把1只4星以下的怪兽特殊召唤。 ②：只要这张卡在怪兽区域存在，对方不能选择其他的战士族怪兽作为攻击对象。'),
(24037702, 'March of the Dark Brigade', '暗之进军', '闇の進軍', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只「光道」怪兽为对象才能发动。那只怪兽加入手卡。那之后，把加入手卡的那只怪兽的原本等级数量的卡从自己卡组上面除外。'),
(19870120, 'March of the Monarchs', '进击的帝王', '進撃の帝王', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，自己场上的上级召唤的怪兽不会成为效果的对象，不会被效果破坏。 ②：只要这张卡在魔法与陷阱区域存在，自己不能从额外卡组把怪兽特殊召唤。'),
(28643791, 'March Towards Ragnarok', '最后的进军', '最後の進軍', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只名字带有「极神」的怪兽发动。直到这个回合的结束阶段时，选择的怪兽的效果无效化，不受这张卡以外的魔法·陷阱卡的效果影响。'),
(13903402, 'Mardel, Generaider Boss of Light', '光之创王 玛戴尔', '光の王 マルデル', 'Effect Monster', 'Plant', 'LIGHT', 9, 2400, 2400, '这个卡名的②的效果1回合只能使用1次。 ①：「光界王战 玛多尔女王」在自己场上只能有1只表侧表示存在。 ②：这张卡召唤·特殊召唤成功的场合才能发动。「光界王战 玛多尔女王」以外的，1张「王战」卡或者1只植物族怪兽从卡组加入手卡。'),
(54537489, 'Mare Mare', '龙落亲', 'タツノオトシオヤ', 'Tuner Monster', 'Wyrm', 'WATER', 7, 2100, 1400, '这张卡不用幻龙族怪兽的效果不能特殊召唤。这个卡名的效果1回合可以使用最多3次。 ①：自己主要阶段才能发动。这张卡的等级下降1星，在自己场上把1只「龙子衍生物」（幻龙族·水·1星·攻300/守200）特殊召唤。'),
(62632427, 'Margin Trading', '信用交易', '信用取引', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方可以丢弃1张手卡让这个效果无效。没丢弃的场合，双方玩家各自把对方卡组确认，从那之中选1张卡。那之后，双方玩家各自把对方选的卡加入手卡。'),
(58205203, 'Mariamne Paradox, the True Dracophoenix Knight', '真龙凰骑 慈育圣母 悖论', '真竜凰騎マリアムネP', 'Effect Monster', 'Wyrm', 'WIND', 6, 1800, 1400, '这张卡表侧表示上级召唤的场合，可以作为怪兽的代替而把自己场上的永续魔法·永续陷阱卡解放。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合才能发动。这张卡以外的自己的手卡·场上（表侧表示）1张「真龙」卡破坏，这张卡在自己或对方的场上特殊召唤。 ②：这张卡从手卡召唤·特殊召唤的场合发动。从自己卡组上面把4张卡除外。'),
(94160895, 'Mariamne, the True Dracophoenix', '真龙凰 慈育圣母', '真竜凰マリアムネ', 'Effect Monster', 'Wyrm', 'WIND', 9, 2700, 2100, '「真龙凰 玛丽亚姆内」的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从这张卡以外的手卡以及自己场上的表侧表示怪兽之中把包含风属性怪兽的2只怪兽破坏，这张卡从手卡特殊召唤，把2只风属性怪兽破坏的场合，可以从对方卡组上面把4张卡除外。 ②：这张卡被效果破坏的场合才能发动。从卡组把1只风属性以外的幻龙族怪兽加入手卡。'),
(78540593, 'Marina, Princess of Sunflowers', '姬葵 玛丽娜', '姫葵マリーナ', 'Effect Monster', 'Plant', 'FIRE', 8, 2800, 1600, '只要这张卡在场上表侧表示存在，这张卡以外的自己场上的植物族怪兽1只被战斗或者卡的效果破坏送去墓地的场合，可以选择对方场上1张卡破坏。'),
(20934852, 'Marincess Aqua Argonaut', '海晶少女 水葵・爱尔格诺特', '海晶乙女アクア・アルゴノート', 'Link Monster', 'Cyberse', 'WATER', NULL, 2300, NULL, '水属性怪兽2只以上 这个卡名的②③的效果1回合各能使用1次。 ①：只要这张卡在额外怪兽区域存在，对方不能向其他怪兽攻击。 ②：以自己场上1只水属性怪兽和对方场上1张卡为对象才能发动。那些卡回到持有者手卡。 ③：对方回合，魔法·陷阱卡的效果在场上发动时才能发动。选给这张卡装备的1张自己的「海晶少女」怪兽卡特殊召唤，那个发动的效果无效。'),
(33945211, 'Marincess Basilalima', '海晶少女 角耳雪锉', '海晶乙女バシランリマ', 'Effect Monster', 'Cyberse', 'WATER', 4, 600, 2100, '这个卡名的①③的效果1回合各能使用1次。 ①：从自己墓地把1张「海晶少女」陷阱卡除外才能发动。和那张卡卡名不同的1张「海晶少女」陷阱卡从卡组加入手卡。 ②：自己场上的怪兽被效果破坏的场合，可以作为代替把墓地的这张卡除外。 ③：这张卡被除外的场合，以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力上升600。'),
(91027843, 'Marincess Battle Ocean', '海晶少女之斗海', '海晶乙女の闘海', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己场上的「海晶少女」怪兽的攻击力上升200，再上升装备的「海晶少女」卡数量×600。 ②：用「海晶少女 水晶心」为素材作连接召唤的额外怪兽区域的自己怪兽不受对方的效果影响。 ③：自己在额外怪兽区域把「海晶少女」连接怪兽连接召唤时才能发动。从自己墓地选最多3只「海晶少女」连接怪兽给那只连接召唤的怪兽当作装备卡使用来装备（同名卡最多1张）。'),
(43735670, 'Marincess Blue Slug', '海晶少女 蓝彩蛞蝓', '海晶乙女ブルースラッグ', 'Link Monster', 'Cyberse', 'WATER', NULL, 1500, NULL, '4星以下的「海晶少女」怪兽1只 自己对「海晶少女 青高海牛」1回合只能有1次连接召唤。 ①：这张卡连接召唤成功的场合，以「海晶少女 青高海牛」以外的自己墓地1只「海晶少女」怪兽为对象才能发动。那只怪兽加入手卡。这个效果的发动后，直到回合结束时自己不是水属性怪兽不能特殊召唤。'),
(91953000, 'Marincess Blue Tang', '海晶少女 蓝彩刺尾', '海晶乙女ブルータン', 'Effect Monster', 'Cyberse', 'WATER', 4, 1500, 1200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「海晶少女 蓝倒吊」以外的1只「海晶少女」怪兽送去墓地。 ②：这张卡作为水属性连接怪兽的连接素材送去墓地的场合才能发动。从自己卡组上面把3张卡翻开。可以从那之中选1张「海晶少女」卡加入手卡。剩下的卡回到卡组。'),
(19712214, 'Marincess Bubble Ring', '海晶少女涡轮', '海晶乙女渦輪', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己或者对方的怪兽的攻击宣言时才能发动。那次攻击无效，从自己的额外卡组·墓地选1只「海晶少女 水晶心」特殊召唤。 ②：把墓地的这张卡除外，以自己场上1只连接2以上的「海晶少女」连接怪兽为对象才能发动。这个回合，那只怪兽在同1次的战斗阶段中可以作出最多有自身的连接标记数量的攻击，那只怪兽的战斗发生的对对方的战斗伤害变成0。'),
(27012990, 'Marincess Cascade', '海晶少女瀑布', '海晶乙女瀑布', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有连接3以上的「海晶少女」怪兽存在的场合，这张卡的发动从手卡也能用。 ①：把自己场上的「海晶少女」连接怪兽任意数量直到下次的自己准备阶段除外，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升因为这张卡发动而除外的连接怪兽的连接标记合计×300。'),
(83723605, 'Marincess Circulation', '海晶少女环流', '海晶乙女環流', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有连接3以上的「海晶少女」怪兽存在的场合，这张卡的发动从手卡也能用。 ①：以自己场上1只水属性连接怪兽为对象才能发动。那只怪兽回到持有者的额外卡组，和那只怪兽是卡名不同并是连接标记数量相同的1只「海晶少女」连接怪兽当作连接召唤从额外卡组特殊召唤。这个回合，这个效果特殊召唤的怪兽不能直接攻击，不会被战斗破坏。'),
(79130389, 'Marincess Coral Anemone', '海晶少女 珊瑚海葵', '海晶乙女コーラルアネモネ', 'Link Monster', 'Cyberse', 'WATER', NULL, 2000, NULL, '水属性怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地1只攻击力1500以下的水属性怪兽为对象才能发动。那只怪兽在作为这张卡所连接区的自己场上特殊召唤。这个效果的发动后，直到回合结束时自己不是水属性怪兽不能特殊召唤。 ②：这张卡从场上送去墓地的场合，以「海晶少女 奶嘴海葵」以外的自己墓地1张「海晶少女」卡为对象才能发动。那张卡加入手卡。'),
(84546257, 'Marincess Coral Triangle', '海晶少女 珊瑚大三角', '海晶乙女コーラルトライアングル', 'Link Monster', 'Cyberse', 'WATER', NULL, 1500, NULL, '「海晶少女」怪兽2只以上 这个卡名的①②的效果1回合各能使用1次，这些效果发动的回合，自己不是水属性怪兽不能特殊召唤。 ①：从手卡把1只水属性怪兽送去墓地才能发动。从卡组把1张「海晶少女」陷阱卡加入手卡。 ②：只有对方场上才有怪兽存在的场合，把墓地的这张卡除外才能发动。连接标记合计直到变成3为止，从自己墓地选水属性连接怪兽任意数量特殊召唤。'),
(54569495, 'Marincess Crown Tail', '海晶少女 冠尾', '海晶乙女クラウンテイル', 'Effect Monster', 'Cyberse', 'WATER', 5, 600, 2300, '这个卡名的①②的效果1回合各能使用1次。 ①：怪兽之间进行战斗的伤害计算时，从手卡把这张卡以外的1只「海晶少女」怪兽送去墓地才能发动。这张卡从手卡特殊召唤，那次战斗发生的对自己的战斗伤害变成一半。 ②：对方怪兽攻击的伤害步骤开始时，把墓地的这张卡除外才能发动。这个回合自己不会受到自己墓地的「海晶少女」连接怪兽的连接标记合计×1000以下的战斗伤害。'),
(67712104, 'Marincess Crystal Heart', '海晶少女 水晶心', '海晶乙女クリスタルハート', 'Link Monster', 'Cyberse', 'WATER', NULL, NULL, NULL, '水属性怪兽2只 ①：这张卡只要在额外怪兽区域存在，不受对方怪兽的效果影响。 ②：这张卡和对方怪兽进行战斗的伤害步骤内，那只对方怪兽不受自身以外的卡的效果影响。 ③：这张卡或者这张卡所连接区的自己的「海晶少女」连接怪兽被选择作为攻击对象时，从手卡把1只「海晶少女」怪兽送去墓地才能发动。那只自己怪兽不会被那次战斗破坏，那次战斗发生的对自己的战斗伤害变成0。'),
(84430165, 'Marincess Current', '海晶少女潮流', '海晶乙女潮流', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。自己场上有连接3以上的「海晶少女」怪兽存在的场合，这张卡的发动从手卡也能用。 ①：自己的「海晶少女」连接怪兽战斗破坏对方怪兽时才能发动。给与对方那只自己怪兽的连接标记数量×400伤害。自己场上有连接2以上的「海晶少女」怪兽存在，破坏对方连接怪兽的场合，再给与对方破坏的怪兽的连接标记数量×500伤害。'),
(57329501, 'Marincess Dive', '海晶少女之潜逅', '海晶乙女の潜逅', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。这张卡的发动后，直到回合结束时自己不是水属性怪兽不能特殊召唤。 ●以连接怪兽以外的自己墓地1只「海晶少女」怪兽为对象才能发动。那只怪兽特殊召唤。 ●自己的场地区域有「海晶少女的斗海」存在的场合才能发动。从卡组把1只「海晶少女」怪兽特殊召唤。'),
(47910940, 'Marincess Great Bubble Reef', '海晶少女 魔泡大堡礁', '海晶乙女グレート・バブル・リーフ', 'Link Monster', 'Cyberse', 'WATER', NULL, 2600, NULL, '水属性怪兽2只以上 这个卡名的③的效果1回合只能使用1次。 ①：双方的准备阶段，从自己墓地以及自己场上的表侧表示怪兽之中把1只水属性怪兽除外才能发动。自己从卡组抽1张。 ②：每次怪兽被除外发动。这张卡的攻击力直到回合结束时上升那些除外的怪兽数量×600。 ③：从手卡把1只水属性怪兽送去墓地才能发动。选除外的1只自己的「海晶少女」怪兽特殊召唤。'),
(28174796, 'Marincess Mandarin', '海晶少女 官服', '海晶乙女マンダリン', 'Effect Monster', 'Cyberse', 'WATER', 1, 100, 100, '这个卡名的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在，自己场上有「海晶少女」怪兽2只以上存在的场合，以自己场上1只水属性连接怪兽为对象才能发动。这张卡在作为那只怪兽所连接区的自己场上特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(5524387, 'Marincess Marbled Rock', '海晶少女 褐菖鲉', '海晶乙女マーブルド・ロック', 'Link Monster', 'Cyberse', 'WATER', NULL, 2500, NULL, '水属性怪兽2只以上 这个卡名的①的效果1回合只能使用1次。 ①：以「海晶少女 石狗公」以外的自己墓地1张「海晶少女」卡为对象才能发动。那张卡加入手卡。 ②：对方怪兽的攻击宣言时，从手卡把1只「海晶少女」怪兽送去墓地才能发动。怪兽不会被那次战斗破坏，那次战斗发生的对自己的战斗伤害变成0。'),
(99885917, 'Marincess Pascalus', '海晶少女 紫红拟花', '海晶乙女パスカルス', 'Effect Monster', 'Cyberse', 'WATER', 4, 1200, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从手卡把「海晶少女 紫红拟花鮨」以外的1只「海晶少女」怪兽守备表示特殊召唤。 ②：把墓地的这张卡除外，以自己墓地1张「海晶少女」魔法·陷阱卡为对象才能发动。那张卡加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(30691817, 'Marincess Sea Angel', '海晶少女 海洋天使', '海晶乙女シーエンジェル', 'Link Monster', 'Cyberse', 'WATER', NULL, 1000, NULL, '4星以下的「海晶少女」怪兽1只 自己对「海晶少女 海天使」1回合只能有1次连接召唤。 ①：这张卡连接召唤成功的场合才能发动。从卡组把1张「海晶少女」魔法卡加入手卡。'),
(36492575, 'Marincess Sea Horse', '海晶少女 海马', '海晶乙女シーホース', 'Effect Monster', 'Cyberse', 'WATER', 3, 1400, 1000, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以从手卡往作为「海晶少女」连接怪兽所连接区的自己场上特殊召唤。 ②：把墓地的这张卡除外才能发动。从手卡把1只水属性怪兽在作为「海晶少女」连接怪兽所连接区的自己场上特殊召唤。这个效果在这张卡送去墓地的回合不能发动。'),
(62886670, 'Marincess Sea Star', '海晶少女 海星', '海晶乙女シースター', 'Effect Monster', 'Cyberse', 'WATER', 2, 800, 400, '这个卡名的效果1回合可以使用最多2次。 ①：把这张卡从手卡送去墓地，以自己场上1只「海晶少女」怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升800。');